#!/usr/bin/env python3
"""Build the FY2027 Senate Committee Report stage comparison and impact audit."""
import csv, json, html
from pathlib import Path

ROOT = Path(__file__).resolve().parent
STATIC = ROOT.parent / 'open-data-visualization/static/nep-preview'
OUT = ROOT / 'analysis_output'
DATA = ROOT / 'data_sources/senate-2027-dataset'

PAGES = [
    ('dpwh.html', 'DPWH project and document analyses', 'Highest priority', 'The SCR dataset has 17,613 DPWH rows, including cuts, renames, additions and allocation changes. Recheck insertion, deletion, title, office and allocation findings; retain a row-level SCR explanation and mark only confirmed resolutions green.'),
    ('dpwh-hgab.html', 'DPWH NEP → HGAB analysis', 'Highest priority', 'Compare the House-stage flags to SCR row disposition. A cut may invalidate a claim that a project remains in the bill; a rename or correction may resolve a title or location concern; a new or raised item may add or worsen a concern.'),
    ('dpwh-OO2-hgab.html', 'DPWH OO2-adjusted candidate analysis', 'High', 'Recheck House-only and insertion candidates against SCR cuts, restored lines, renames and amount changes. Keep the earlier HGAB evidence and annotate its later disposition.'),
    ('dpwh-hgab-comparison.html', 'House reading comparison', 'High', 'Add the next stage to the existing reading timeline where rows can be linked reliably; avoid treating stage totals as additive allocations.'),
    ('fmr.html', 'Farm-to-market roads', 'High', 'The SCR includes 1,200 FMR rows and 141 Senate additions. Reassess project presence, restoration, amount changes and title/location concerns.'),
    ('nia.html', 'NIA projects', 'High', 'The SCR includes 1,117 NIA rows, including renames, cuts, additions and restorations. Recheck project identity, scope and amount flags.'),
    ('hfep.html', 'Health Facilities Enhancement Program', 'High', 'The SCR includes 905 HFEP rows. Facility/component matches can resolve or add project-level flags; confirm facility identity before changing an existing finding.'),
    ('repeats.html', 'Project repeats', 'Medium', 'SCR stage status can show that an apparent repeat was cut, renamed or retained. It does not establish whether two projects are duplicates; preserve repeat evidence and annotate the later stage.'),
    ('out-of-place.html', 'Out of Place', 'Medium', 'Recheck location and attribution concerns when the SCR renames or changes an item. The report’s own correction is useful evidence, but does not independently validate geographic attribution.'),
    ('congress.html', 'Project flags and district allocations', 'Medium', 'Reassess district and insertion flags for the four covered schedules. Preserve prior-stage results and add SCR evidence only for reliably linked rows.'),
    ('flags.html', 'Flag index', 'Medium', 'Best destination for a compact SCR status badge and a link to the Senate report page, once flags are joined to project IDs.'),
    ('cost-per-km.html', 'Cost per meter', 'Conditional', 'Recalculate only where SCR changes the comparable project scope or allocation and the metric uses an affected schedule. A budget change alone is not a unit-cost finding.'),
]

def load_csv(name):
    with (DATA / name).open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))

def money(v):
    try: return int(float(v or 0))
    except (ValueError, TypeError): return 0

def peso(v): return '₱' + format(round(v), ',')

def build():
    rows = load_csv('senate-2027-projects.csv')
    summary_rows = load_csv('senate-2027-general-summary.csv')
    checks = load_csv('senate-2027-checks.csv')
    provisions = load_csv('senate-2027-provisions.csv')
    annex = load_csv('senate-2027-annex-a.csv')
    by_program = {}
    for r in rows:
        prog = r['program']; agg = by_program.setdefault(prog, {'rows':0,'changed':0,'cut':0,'added':0,'raised':0,'reduced':0,'restored':0,'renamed':0,'unchanged':0,'nep_only':0,'grossCut':0,'grossAdded':0,'grossRaised':0,'grossReduced':0})
        agg['rows'] += 1
        st = r['status']
        if st in agg: agg[st] += 1
        if st not in ('unchanged','nep_only'): agg['changed'] += 1
        if st == 'cut': agg['grossCut'] += abs(money(r['house_php']))
        if st in ('added','restored'): agg['grossAdded'] += money(r['senate_php'])
        if st == 'raised': agg['grossRaised'] += max(0, money(r['senate_php']) - money(r['house_php']))
        if st == 'reduced': agg['grossReduced'] += max(0, money(r['house_php']) - money(r['senate_php']))
    # Only the four annexed schedules have row-level projects in the dataset.
    slim = []
    for r in rows:
        slim.append({k:r.get(k,'') for k in ('program','id','house_id','status','status_label','title','house_title','region','office','program_line','pap','nep_php','house_php','senate_php','vs_house_php','vs_nep_php','inserted_by_house','replaces_id','senate_doc','senate_page','senate_pdf_url','house_doc','house_page','house_pdf_url','nep_doc','nep_page','nep_pdf_url','page_url','matched_by','check_id','check_note')})
    data = {'source':'data_sources/senate-2027-dataset','rows':slim}
    summary_by_dept=[]
    for r in summary_rows:
        if r['level'] in ('department','total'):
            summary_by_dept.append({'level':r['level'],'department':r['department'],'nep':money(r['nep_php']),'house':money(r['house_php']),'net':money(r['net_php']),'senate':money(r['house_php'])+money(r['net_php'])})
    # Keep exact check results accessible as source-quality context.
    checks_ok=sum(1 for c in checks if str(c['ok']).lower() in ('true','1','yes'))
    dpwh_tot=next((r for r in summary_by_dept if r['department']=='DEPARTMENT OF PUBLIC WORKS AND HIGHWAYS'),{})
    audit_html=''.join('<tr><td><a href="'+html.escape(path)+'">'+html.escape(path)+'</a><br>'+html.escape(label)+'</td><td>'+html.escape(priority)+'</td><td>'+html.escape(note)+'</td></tr>' for path,label,priority,note in PAGES)
    cards=''.join(f'<article class="stat"><small>{p.upper()}</small><strong>{a["rows"]:,}</strong><span>rows · {a["changed"]:,} not unchanged/NEP-only</span><span>{a["cut"]:,} cuts · {a["added"]:,} additions · {a["restored"]:,} restored</span></article>' for p,a in sorted(by_program.items()))
    payload=''
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FY2027 Senate Committee Report · NEP → HGAB → SCR</title><style>
:root{{--ink:#162019;--muted:#5d6b61;--line:#dce5dc;--paper:#f7faf7;--green:#126339;--red:#a52c25;--amber:#8a5a00}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}}main{{max-width:1240px;margin:auto;padding:24px}}h1{{font-size:clamp(30px,5vw,48px);line-height:1.08;margin:.3em 0}}h2{{font-size:24px;margin:0 0 10px}}h3{{font-size:18px;margin:0 0 8px}}p{{margin:.4em 0 1em}}.eyebrow{{color:var(--green);font-weight:750;letter-spacing:.07em;text-transform:uppercase}}.lead{{font-size:18px;max-width:900px;color:#344238}}.hero,.card{{background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin:18px 0}}.stats{{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin:18px 0}}.stat{{background:#fff;border:1px solid var(--line);border-radius:12px;padding:15px;display:flex;flex-direction:column}}.stat strong{{font-size:30px}}.stat small{{color:var(--green);font-weight:750}}.stat span,.muted{{color:var(--muted)}}.metric{{font-size:28px;font-weight:800}}.rules{{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}}.rule{{border:1px solid var(--line);border-radius:10px;padding:14px}}.green{{color:var(--green)}}.red{{color:var(--red)}}.amber{{color:var(--amber)}}.controls{{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0}}input,select,button{{font:inherit;padding:9px 11px;border:1px solid #b9c9bb;border-radius:8px;background:#fff}}input{{min-width:240px;flex:1}}button{{cursor:pointer}}.tablewrap{{overflow:auto;max-height:70vh;border:1px solid var(--line);border-radius:8px}}table{{border-collapse:collapse;width:100%;background:#fff;font-size:13px}}th,td{{padding:9px 10px;border-bottom:1px solid #e5ebe5;text-align:left;vertical-align:top}}th{{position:sticky;top:0;background:#edf3ed;z-index:1}}td.amount,th.amount{{text-align:right;white-space:nowrap}}.pill{{display:inline-block;padding:2px 8px;border-radius:30px;background:#edf2ed;font-size:12px;font-weight:700}}.pill.cut,.pill.added,.pill.raised,.pill.reduced{{background:#fbe9e7;color:var(--red)}}.pill.restored,.pill.renamed{{background:#e4f4e9;color:var(--green)}}.note{{border-left:4px solid #d4a72c;padding:10px 14px;background:#fff9e8}}a{{color:#125d3c}}.small{{font-size:13px}}@media(max-width:640px){{main{{padding:14px}}.tablewrap{{max-height:65vh}}}}
</style></head><body><main><header class="hero"><div class="eyebrow">FY2027 · Next budget stage</div><h1>NEP → HGAB → Senate committee report</h1><p class="lead">Compare House bill rows against the Senate Committee on Finance’s report on HB 10858. Continue the evidence trail toward GAB, Bicam and GAA while keeping each version distinct.</p><p class="note"><strong>Under citizen review.</strong> This is an unofficial reading of the Senate report. Open the cited report page before relying on a row. Appropriations at different stages are versions of one budget; never add them together.</p></header>
<section class="stats">{cards}</section><section class="card"><h2>What the report changes at a glance</h2><p>DPWH’s General Summary allocation moves from <strong>{peso(dpwh_tot.get('house',0))}</strong> in the House bill to <strong>{peso(dpwh_tot.get('senate',0))}</strong> in the Senate report: net <strong class="red">{peso(dpwh_tot.get('net',0))}</strong>. The project dataset separately marks {by_program.get('dpwh',{}).get('cut',0):,} DPWH rows as cut, representing <strong>{peso(by_program.get('dpwh',{}).get('grossCut',0))}</strong> in gross House allocations. Gross cuts and the net department change are different measures: raises, reductions and additions also affect the total.</p><p>The dataset has <strong>{len(rows):,} project rows</strong>, {len(annex):,} Annex A rows, {len(provisions):,} Annex B provision amendments, and {checks_ok}/{len(checks)} listed checks passing. Source definitions, caveats and documents are recorded in the supplied dataset README.</p></section>
<section class="card"><h2>How SCR changes should affect existing flags</h2><div class="rules"><div class="rule"><h3 class="green">Green · resolved or corrected</h3><p>Keep the original HGAB flag and add an SCR note when the cited Senate change directly resolves it: for example, the line is cut, a title/location is corrected, or the amount/scope concern is explicitly corrected. The note should cite the SCR page and say what changed.</p></div><div class="rule"><h3 class="red">Red · new or worse</h3><p>Add a red flag when SCR adds a project that triggers an existing flag rule, or when a Senate revision introduces or strengthens a concern (such as a larger amount, broader scope or a new location/attribution issue). Cite the report page and state the rule triggered.</p></div><div class="rule"><h3 class="amber">Review · stage change alone</h3><p>A cut, rename, addition or increase is not automatically a finding. Match the row to the original flag and its rule first. Preserve historical HGAB evidence, then annotate the later status so the reader can see how the finding changed over time.</p></div></div><p class="small muted">This page marks stage disposition from the published dataset. It does not automatically claim that any specific existing flag is invalid or newly substantiated; that requires a defensible row-to-flag match.</p></section>
<section class="card"><h2>Which analyses can benefit from SCR</h2><p>Prioritized by schedule coverage and whether a later-stage row can change the evidence behind a flag.</p><div class="tablewrap"><table><thead><tr><th>Page</th><th>Priority</th><th>Potential SCR comparison</th></tr></thead><tbody>{audit_html}</tbody></table></div></section>
<section class="card"><h2>Project row comparison</h2><p>Search Senate, House or NEP title and row identifiers. By default, unchanged and NEP-only rows are hidden so review focuses on SCR-stage changes. Every displayed row retains source page links for all available stages. Status labels describe the SCR disposition; they are not themselves red or green flag judgments.</p><div class="controls"><input id="q" type="search" placeholder="Search project, office, region, ID…"><select id="program"><option value="">All schedules</option><option value="dpwh">DPWH</option><option value="fmr">FMR</option><option value="nia">NIA</option><option value="hfep">HFEP</option></select><select id="status"><option value="changed">Changed / reviewed rows</option><option value="all">All rows</option><option value="cut">Cut</option><option value="added">Added</option><option value="restored">Restored</option><option value="renamed">Renamed</option><option value="raised">Raised</option><option value="reduced">Reduced</option><option value="unchanged">Unchanged</option><option value="nep_only">NEP only</option></select><span id="count" aria-live="polite"></span></div><div class="tablewrap"><table><thead><tr><th>Schedule / status</th><th>Senate report title</th><th>House bill title</th><th>Office / region</th><th class="amount">NEP</th><th class="amount">House</th><th class="amount">Senate</th><th>SCR evidence</th><th>Stage sources</th></tr></thead><tbody id="rows"></tbody></table></div><div class="controls"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div><p class="small muted">Rows shown <span id="range"></span>. Amounts are pesos. A blank amount means the source dataset does not supply one for that stage.</p></section>
<section class="card"><h2>Sources and method</h2><p>The data comes from the supplied <code>senate-2027-dataset</code> package. It covers Senate project schedules for DPWH, DA farm-to-market roads, DOH HFEP and NIA; it is not a complete row-level transcription of every department. Department-wide amounts come from the report’s General Summary. Status and matching conventions are defined in the linked README.</p><p>Source validation recorded by the build: {checks_ok} of {len(checks)} checks pass; the README records page-level misses and describes the remaining review needed. The report pages are evidence references, not proof of implementation or spending.</p></section>
</main><script>let DATA={{rows:[]}};
const fmt=v=>v===''||v==null?'—':'₱'+Number(v).toLocaleString('en-US');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
let page=0;const size=50;function render(){{const q=document.querySelector('#q').value.toLowerCase(), prog=document.querySelector('#program').value, st=document.querySelector('#status').value;let data=DATA.rows.filter(r=>(!prog||r.program===prog)&&(st==='all'||(st==='changed'?!['unchanged','nep_only'].includes(r.status):r.status===st))&&(!q||[r.id,r.house_id,r.title,r.house_title,r.office,r.region,r.pap,r.check_note].join(' ').toLowerCase().includes(q)));const total=data.length;const pages=Math.max(1,Math.ceil(total/size));page=Math.min(page,pages-1);const shown=data.slice(page*size,(page+1)*size);document.querySelector('#count').textContent=total.toLocaleString()+' matching rows';document.querySelector('#page').textContent=`Page ${{page+1}} of ${{pages}}`;document.querySelector('#range').textContent=total?`${{page*size+1}}–${{Math.min((page+1)*size,total)}} of ${{total.toLocaleString()}}`:'0';document.querySelector('#rows').innerHTML=shown.map(r=>`<tr><td><strong>${{esc(r.program.toUpperCase())}}</strong><br><span class="pill">${{esc(r.status_label||r.status)}}</span><br><span class="small">${{esc(r.id)}}</span></td><td>${{esc(r.title)}}</td><td>${{esc(r.house_title||'—')}}</td><td>${{esc(r.office||'—')}}<br>${{esc(r.region||'')}}</td><td class="amount">${{fmt(r.nep_php)}}</td><td class="amount">${{fmt(r.house_php)}}</td><td class="amount">${{fmt(r.senate_php)}}</td><td>${{esc(r.check_note||r.matched_by||'—')}}${{r.senate_pdf_url?`<br><a href="${{esc(r.senate_pdf_url)}}" target="_blank" rel="noopener">SCR p. ${{esc(r.senate_page||'open')}}</a>`:''}}</td><td>${{r.nep_pdf_url?`<a href="${{esc(r.nep_pdf_url)}}" target="_blank" rel="noopener">NEP p. ${{esc(r.nep_page||'open')}}</a>`:''}} ${{r.house_pdf_url?`<br><a href="${{esc(r.house_pdf_url)}}" target="_blank" rel="noopener">House p. ${{esc(r.house_page||'open')}}</a>`:''}} ${{r.page_url?`<br><a href="${{esc(r.page_url)}}" target="_blank" rel="noopener">BetterGov row</a>`:''}}</td></tr>`).join('');document.querySelector('#prev').disabled=page===0;document.querySelector('#next').disabled=page>=pages-1}}document.querySelectorAll('#q,#program,#status').forEach(x=>x.addEventListener('input',()=>{{page=0;render()}}));document.querySelector('#prev').onclick=()=>{{page--;render()}};document.querySelector('#next').onclick=()=>{{page++;render()}};fetch('scr-data.json').then(r=>{{if(!r.ok)throw Error('Could not load SCR project data');return r.json()}}).then(d=>{{DATA=d;render()}}).catch(e=>{{document.querySelector('#count').textContent=e.message}});</script></body></html>'''
    STATIC.mkdir(parents=True,exist_ok=True); OUT.mkdir(parents=True,exist_ok=True)
    from uniform_report_menu import apply_page as apply_uniform_menu
    page=apply_uniform_menu(page,'scr.html')
    serialized=json.dumps(data,ensure_ascii=False,separators=(',',':'))
    (STATIC/'scr.html').write_text(page,encoding='utf-8')
    (OUT/'scr.html').write_text(page,encoding='utf-8')
    (STATIC/'scr-data.json').write_text(serialized,encoding='utf-8')
    (OUT/'scr-data.json').write_text(serialized,encoding='utf-8')
    print(json.dumps({'page':str(OUT/'scr.html'),'publishedPage':str(STATIC/'scr.html'),'projects':len(rows),'checksPassed':checks_ok,'checksTotal':len(checks),'programs':by_program},ensure_ascii=False))

if __name__=='__main__': build()
